mapper.select:
SELECT DISTINCT g.sku_id
FROM pm_promo_goods_sku g
INNER JOIN pm_promo_activity a ON a.id = g.activity_id AND a.del_flag = '0'
WHERE g.del_flag = '0'
  AND g.tenant_id = #{tenantId}
  AND g.sku_id IN

      #{skuId}

  AND a.promo_type IN ('SPECIAL_PRICE', 'SECKILL')
  AND a.status IN (0, 1, 2)
  AND a.start_time < #{endTime}
  AND a.end_time > #{startTime}

      AND a.id != #{excludeActivityId}

mapper.update:
UPDATE pm_promo_goods_sku
SET sold_stock = IFNULL(sold_stock, 0) + #{qty},
    version = IFNULL(version, 0) + 1
WHERE del_flag = '0'
  AND tenant_id = #{tenantId}
  AND activity_id = #{activityId}
  AND sku_id = #{skuId}
  AND (
      activity_stock = -1
      OR activity_stock - IFNULL(sold_stock, 0) >= #{qty}
  )

UPDATE pm_promo_goods_sku
SET sold_stock = GREATEST(IFNULL(sold_stock, 0) - #{qty}, 0),
    version = IFNULL(version, 0) + 1
WHERE del_flag = '0'
  AND tenant_id = #{tenantId}
  AND activity_id = #{activityId}
  AND sku_id = #{skuId}
  AND IFNULL(sold_stock, 0) >= #{qty}
